<script setup lang="ts">
import { Clock3, RefreshCw, RadioTower } from 'lucide-vue-next'
import type { Crop, CropCycle, DashboardResponse, Station } from '~/types/api'
useSeoMeta({ title: 'Clima y alertas' })
const { request }=useApi(); const selection=useSelectionStore(); const stations=ref<Station[]>([]); const crops=ref<Crop[]>([]); const cycles=ref<CropCycle[]>([]); const dashboard=ref<DashboardResponse|null>(null); const loading=ref(true); const error=ref('')
const chartLabels=computed(()=>dashboard.value?.series.map(x=>new Date(String(x.sampled_at)).toLocaleString('es-PY',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}))||[])
const temperatureData=computed(()=>[{label:'Temperatura °C',data:dashboard.value?.series.map(x=>x.temperature_c as number|null)||[]},{label:'Humedad %',data:dashboard.value?.series.map(x=>x.humidity_pct as number|null)||[]}])
const rainData=computed(()=>[{label:'Lluvia mm',data:dashboard.value?.series.map(x=>x.rain_mm as number|null)||[]},{label:'Humedad suelo %',data:dashboard.value?.series.map(x=>x.soil_moisture_pct as number|null)||[]}])
async function loadSelectors(){const [s,c]=await Promise.all([request<Station[]>('/public/stations'),request<Crop[]>('/public/crops')]);stations.value=s;crops.value=c;if(!selection.stationId&&s[0])selection.stationId=s[0].id;if(!c.some(x=>x.code===selection.cropCode)&&c[0])selection.cropCode=c[0].code;await loadCycles()}
async function loadCycles(){if(!selection.stationId){cycles.value=[];return}cycles.value=await request<CropCycle[]>('/public/crop-cycles',{query:{station_id:selection.stationId,crop_code:selection.cropCode}});if(selection.cycleId&&!cycles.value.some(x=>x.id===selection.cycleId))selection.cycleId=''}
async function loadDashboard(){if(!selection.stationId)return;loading.value=true;error.value='';try{dashboard.value=await request<DashboardResponse>('/public/dashboard',{query:{station_id:selection.stationId,crop_code:selection.cropCode,cycle_id:selection.cycleId||undefined,period:selection.period}})}catch(e:any){error.value=e?.data?.detail||e?.message||'No se pudo cargar el tablero'}finally{loading.value=false}}
watch(()=>[selection.stationId,selection.cropCode],async()=>{await loadCycles();await loadDashboard()});watch(()=>[selection.cycleId,selection.period],loadDashboard)
onMounted(async()=>{try{await loadSelectors();await loadDashboard()}catch(e:any){error.value=e?.data?.detail||'No se pudo conectar con el API';loading.value=false}})
</script>
<template><div class="page"><div class="container"><header class="dashboard-head"><div><h1 class="page-title">Clima, cultivo y decisiones oportunas</h1><p class="page-subtitle">Lecturas observadas, alertas determinísticas y explicaciones sencillas para productores.</p></div><button class="btn btn-secondary" :disabled="loading" @click="loadDashboard"><RefreshCw/> Actualizar</button></header><section class="selector-panel card"><div class="card-body selector-grid"><GlobalStationSelector v-model="selection.stationId" :stations="stations" :loading="loading"/><GlobalCropSelector v-model="selection.cropCode" :crops="crops"/><GlobalCropCycleSelector v-model="selection.cycleId" :cycles="cycles"/><label><span class="label">Periodo de gráficos</span><select v-model="selection.period" class="select"><option value="24h">24 horas</option><option value="72h">72 horas</option><option value="7d">7 días</option><option value="30d">30 días</option></select></label></div></section><ErrorState v-if="error" :message="error" @retry="loadDashboard"/><LoadingState v-else-if="loading"/><template v-else-if="dashboard"><section class="station-bar"><div><RadioTower/><div><b>{{dashboard.station.name}}</b><span>{{[dashboard.station.locality,dashboard.station.department].filter(Boolean).join(', ')||'Ubicación no registrada'}}</span></div></div><div class="station-status"><span class="badge" :class="dashboard.connection_status==='online'?'badge-success':dashboard.connection_status==='delayed'?'badge-warning':'badge-danger'">{{dashboard.connection_status}}</span><span><Clock3/> {{dashboard.latest_reading_at?new Date(dashboard.latest_reading_at).toLocaleString('es-PY'):'Sin lectura'}}</span></div></section><section class="grid metrics-grid"><WeatherMetricCard v-for="metric in dashboard.metrics" :key="metric.key" :metric="metric"/></section><section class="grid grid-2 major-grid"><AlertStatusCard :alert="dashboard.alert"/><DataQualityCard :quality="dashboard.data_quality"/></section><section class="section-block"><h2 class="section-title">Enfermedades potencialmente favorecidas</h2><div v-if="dashboard.alert.diseases.length" class="grid grid-3"><DiseaseRiskCard v-for="d in dashboard.alert.diseases" :key="d.name" :disease="d"/></div><div v-else class="card"><EmptyState title="Sin coincidencias publicadas" message="No se detectaron reglas de enfermedad publicadas para la etapa y los datos disponibles."/></div></section><section class="grid grid-2 section-block"><ChartContainer title="Temperatura y humedad" subtitle="Serie observada en la estación"><WeatherLineChart :labels="chartLabels" :datasets="temperatureData"/></ChartContainer><ChartContainer title="Lluvia y suelo" subtitle="Los vacíos se muestran sin estimar"><WeatherLineChart :labels="chartLabels" :datasets="rainData"/></ChartContainer></section><section id="pronostico" class="section-block"><h2 class="section-title">Pronóstico complementario</h2><div v-if="dashboard.forecast.length" class="forecast-grid"><article v-for="day in dashboard.forecast" :key="String(day.date)" class="card forecast"><b>{{new Date(String(day.date)+'T12:00:00').toLocaleDateString('es-PY',{weekday:'short',day:'2-digit',month:'short'})}}</b><span>{{day.temperature_max_c}}° / {{day.temperature_min_c}}°</span><small>Lluvia {{day.precipitation_mm??0}} mm · {{day.precipitation_probability_pct??0}}%</small></article></div><div v-else class="card"><EmptyState title="Pronóstico no configurado" message="Configure Open-Meteo u otro proveedor desde Integraciones."/></div></section><section class="grid grid-2 section-block"><SatelliteStatusCard :data="dashboard.satellite"/><article class="card"><div class="card-body"><h2 class="section-title">Recomendación del agente</h2><template v-if="dashboard.recommendation"><p class="recommendation">{{dashboard.recommendation.resumen}}</p><h3>Acciones recomendadas</h3><ul><li v-for="a in dashboard.recommendation.acciones_recomendadas" :key="String(a)">{{a}}</li></ul><p class="notice notice-warning small">Cualquier aplicación fitosanitaria debe validarse con un profesional y respetar el registro y la etiqueta vigente en Paraguay.</p></template><div v-else class="notice">El análisis determinístico está disponible. La explicación técnica del agente no está configurada o no pudo generarse.</div></div></article></section></template><div v-else class="card"><EmptyState/></div></div></div></template>
<style scoped>.dashboard-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:22px}.dashboard-head .btn svg{width:18px}.selector-panel{margin-bottom:20px}.selector-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.station-bar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:18px;padding:14px 18px;color:#fff;background:var(--fc-primary);border-radius:var(--fc-radius)}.station-bar>div{display:flex;align-items:center;gap:11px}.station-bar svg{width:25px}.station-bar b,.station-bar span{display:block}.station-bar span{font-size:.82rem;color:#d7edf9}.station-status span{display:inline-flex;align-items:center;gap:6px}.station-status .badge{color:inherit}.station-status svg{width:16px}.major-grid,.section-block{margin-top:22px}.forecast-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:13px}.forecast{padding:16px;box-shadow:none;display:flex;flex-direction:column;gap:6px}.forecast b{color:var(--fc-primary);text-transform:capitalize}.forecast span{font-size:1.15rem;font-weight:900}.forecast small{color:var(--fc-text-muted)}.recommendation{font-size:1.05rem;line-height:1.65}li{margin-bottom:8px}@media(max-width:1050px){.selector-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.dashboard-head,.station-bar{align-items:flex-start;flex-direction:column}.selector-grid{grid-template-columns:1fr}.station-status{align-items:flex-start!important;flex-direction:column}.dashboard-head .btn{width:100%}}</style>
